<script setup lang="ts">
import { computed, ref } from 'vue'
import { typeIcons, typeLabels } from '../../schemas/src/index'
import { assetUrl, canEdit, dateLabel, projectDocuments } from './state'
const props = defineProps<{ type: string; title: string }>()
const query = ref(''); const module = ref('Tất cả modules'); const tag = ref('Tất cả tags'); const role = ref('Tất cả vai trò'); const mode = ref('cards')
const candidates = computed(() => projectDocuments.value.filter(d => d.metadata.type === props.type))
const modules = computed(() => ['Tất cả modules', ...new Set(candidates.value.map(d => d.metadata.module))])
const tags = computed(() => ['Tất cả tags', ...new Set(candidates.value.flatMap(d => d.metadata.tags))])
const roles = computed(() => ['Tất cả vai trò', ...new Set(candidates.value.flatMap(d => d.metadata.related_ids.filter(id => id.startsWith('ROLE-'))))])
const docs = computed(() => candidates.value.filter(d => (module.value === 'Tất cả modules' || d.metadata.module === module.value) && (tag.value === 'Tất cả tags' || d.metadata.tags.includes(tag.value)) && (role.value === 'Tất cả vai trò' || d.metadata.related_ids.includes(role.value)) && `${d.metadata.title} ${d.metadata.doc_id} ${d.body}`.toLocaleLowerCase().includes(query.value.toLocaleLowerCase())))
</script>
<template>
  <div class="breadcrumb-line"><a href="/">Knowledge Hub</a><v-icon icon="mdi-chevron-right" size="16" /><span>{{ title }}</span></div><header class="page-heading"><div><span class="eyebrow">KHÁM PHÁ · {{ typeLabels[type]?.toUpperCase() }}</span><h1>{{ title }}</h1><p>Tra cứu tài liệu đã xuất bản, kết nối nghiệp vụ qua từng ID.</p></div><v-btn v-if="canEdit" color="primary" prepend-icon="mdi-plus" :href="`/studio/?new=${type}`">Tạo tài liệu</v-btn></header>
  <div class="catalog-toolbar"><v-text-field v-model="query" prepend-inner-icon="mdi-magnify" placeholder="Tìm theo tên, ID hoặc nội dung" hide-details aria-label="Lọc tài liệu" /><v-select v-model="module" :items="modules" hide-details aria-label="Lọc module" /><v-select v-model="tag" :items="tags" hide-details aria-label="Lọc tag" /><v-select v-if="type === 'screen'" v-model="role" :items="roles" hide-details aria-label="Lọc business role" /><v-btn-toggle v-model="mode" mandatory density="compact" color="primary"><v-btn value="cards" icon="mdi-view-grid-outline" aria-label="Dạng thẻ" /><v-btn value="table" icon="mdi-format-list-bulleted" aria-label="Dạng danh sách" /></v-btn-toggle></div><div class="catalog-count">{{ docs.length }} tài liệu <span class="status-dot"></span> Published</div>
  <div v-if="mode === 'cards'" class="catalog-grid"><a v-for="doc in docs" :key="doc.metadata.doc_id" :href="doc.url" class="catalog-card"><div v-if="doc.metadata.screen?.screenshot.cover" class="catalog-image"><img :src="assetUrl(doc, doc.metadata.screen.screenshot.cover)" :alt="doc.metadata.screen.screenshot.gallery.find(i => i.path === doc.metadata.screen?.screenshot.cover)?.alt || doc.metadata.title" loading="lazy" /></div><div v-else class="catalog-illustration"><v-icon :icon="typeIcons[type]" size="50" /><span>{{ typeLabels[type] }}</span></div><div class="catalog-card-body"><div class="catalog-card-meta"><code>{{ doc.metadata.doc_id }}</code><v-chip variant="tonal" color="success">Published</v-chip></div><h2>{{ doc.metadata.title }}</h2><p>{{ doc.metadata.summary }}</p><div class="catalog-tags"><span>{{ doc.metadata.module }}</span><span v-for="item in doc.metadata.tags" :key="item">{{ item }}</span></div><div class="catalog-card-foot"><span>{{ doc.metadata.owner }}</span><span>{{ dateLabel(doc.metadata.updated_at) }} <v-icon size="16" icon="mdi-arrow-top-right" /></span></div></div></a></div>
  <div v-else class="panel catalog-table"><table><thead><tr><th>Tài liệu</th><th>Module</th><th>Owner</th><th>Phiên bản</th><th>Cập nhật</th></tr></thead><tbody><tr v-for="doc in docs" :key="doc.metadata.doc_id"><td><a :href="doc.url"><strong>{{ doc.metadata.title }}</strong><small>{{ doc.metadata.doc_id }}</small></a></td><td>{{ doc.metadata.module }}</td><td>{{ doc.metadata.owner }}</td><td>{{ doc.metadata.version }}</td><td>{{ dateLabel(doc.metadata.updated_at) }}</td></tr></tbody></table></div><div v-if="!docs.length" class="empty-state"><v-icon icon="mdi-file-search-outline" size="45" /><h2>Chưa có tài liệu phù hợp</h2><p>Thử thay đổi từ khóa hoặc bộ lọc.</p></div>
</template>
